namespace Plugin.AncientCivilization
{
    public enum AncientRouteAction { Talk, Blade, Relay, Ambush, Wire, Throw }
    public sealed class AncientRouteStop
    {
        public readonly AncientRouteAction Action;public readonly bool Optional;
        public readonly string Title,Speaker,Problem,Reply,Evidence,Outcome,Closing;
        public AncientRouteStop(AncientRouteAction action,string title,string speaker,string problem,string reply,string evidence,string outcome,string closing,bool optional=false)
        {Optional=optional;Action=action;Title=title;Speaker=speaker;Problem=problem;Reply=reply;Evidence=evidence;Outcome=outcome;Closing=closing;}
    }
    // Six required and three optional stops in each lower case, in physical road order.
    public static class AncientLowerRouteData
    {
        static AncientRouteStop D(AncientRouteAction a,string title,string who,string problem,string reply,string evidence,string outcome,string closing)
        {return new AncientRouteStop(a,title,who,problem,reply,evidence,outcome,closing);}
        static readonly AncientRouteStop[] RequiredStops={
            D(AncientRouteAction.Talk,"남겨진 교대표","하역원 태수","아까 트럭은 잡으셨다면서요. 그런데 창고 숫자는 아직 모자라요.","검거한 물량과 그전에 나간 물량을 나눠 확인하겠습니다.","저는 자정에 퇴근했습니다. 제 도장이 새벽 출고에도 찍혀 있어요.","교대표 원본은 여기 있습니다. 제 이름을 지워 달라는 뜻은 아니에요.","그 시간에 어디 계셨는지도 함께 기록하겠습니다."),
            D(AncientRouteAction.Ambush,"증언을 막는 사람들","하역원 태수","서류를 꺼내자 경비가 문을 막았어요. 공장 경비복도 아니에요.","뒤쪽 안전선으로 물러나세요. 통로부터 확보하겠습니다.","저 사람들은 코어보다 장부를 먼저 찾았어요.","이제 나갈 수 있겠네요. 저쪽 계량실에도 사람이 남았습니다.","물건을 지키는 경비가 왜 증언부터 막았는지 확인하죠."),
            D(AncientRouteAction.Blade,"덧씌운 봉인","계량원 도진","계량기 위에 새 철판을 덮었어요. 고장이라는 안내만 붙였고요.","원래 계량기를 손상시키지 않고 덮개만 자르겠습니다.","고장 접수는 오늘인데 새 봉인의 날짜는 어제입니다.","숫자가 살아 있네요. 전원이 꺼진 적도 없었던 것 같아요.","고장 기록과 실제 가동 기록을 따로 확보하겠습니다."),
            D(AncientRouteAction.Talk,"두 개의 계량기","계량원 도진","왼쪽은 주민용, 오른쪽은 예비분이에요. 같은 코어인데 장부가 달라요.","예비분의 수령자는 누구입니까?","목적지를 입력하는 칸 자체가 없어요. 승인번호만 받습니다.","예비분 계량기는 야간에도 돌았어요. 주민 배급은 멈췄는데요.","수령처가 없다는 사실도 기록입니다."),
            D(AncientRouteAction.Ambush,"출고로 봉쇄","운송원 수진","출고 확인서를 넘기려는데 통로가 잠겼어요.","옆 통신함에서 기다리세요. 이동로를 열겠습니다.","봉쇄 신호는 경찰망이 아니라 화물 관제망에서 왔습니다.","전표는 동쪽 단말에 있어요. 검거된 트럭 번호도 남아 있고요.","경찰의 검거 보고보다 봉쇄가 빨랐다는 말이군요."),
            D(AncientRouteAction.Talk,"빈 수령인 칸","운송원 수진","수령인 이름은 비워 두래요. 그러면 책임도 빈칸이 되나요?","승인한 곳과 실제 가져간 사람을 각각 찾겠습니다.","같은 번호의 전표가 두 장입니다. 한 장만 주민 배정이에요.","사본을 챙겨 주세요. 원본은 위에서 가져갈 겁니다.","둘 다 같은 시각에 존재했다는 것부터 남기죠."),
            D(AncientRouteAction.Blade,"눌린 비상 도관","배관공 선우","트럭이 지나간 뒤 비상 도관이 눌렸어요. 안쪽 문은 전기가 있어야 열립니다.","걸린 절연판부터 잘라내겠습니다.","주 전력선은 멀쩡해요. 비상선만 따로 막혔습니다.","압력이 내려갑니다. 이제 정비반이 밸브를 만질 수 있어요.","절단한 판도 버리지 마세요. 봉인 번호가 남아 있습니다."),
            D(AncientRouteAction.Relay,"수동 예비 전원","배관공 선우","이 수광부에 에너지를 넣으면 통신등을 켤 수 있어요.","파편의 입자를 모아 레이저로 전력을 넣겠습니다.","부족하면 옆 노란 절연판을 다시 잘라도 됩니다. 예비판은 남아 있어요.","안쪽에서 응답이 왔어요. 작업자가 아직 있답니다.","복구한 선은 유지하세요. 사람을 확인하러 갑니다."),
            D(AncientRouteAction.Ambush,"복구를 막는 경비","전기공 가람","복구 승인을 기다리라는데 경비가 수광부를 겨누고 있어요.","허가를 기다리다 안쪽 사람이 다칠 수 있습니다. 물러나세요.","저 경비는 공장 안전 신호를 듣지 않아요.","통신등이 다시 켜졌습니다. 현장 복구 시각을 남겼어요.","명령을 받은 시각도 지우지 마세요."),
            D(AncientRouteAction.Talk,"승인보다 빠른 구조","전기공 가람","기록에는 작업장 전원 차단 완료라고 떠요. 구조 요청은 접수 중이고요.","차단 담당과 구조 담당이 다른 겁니까?","차단은 직할 명령, 구조는 하층 심사라고 써 있어요.","사람은 같은 문 안에 있는데 서류는 다른 층으로 가네요.","우선 문을 엽니다. 책임은 제 보고서에 적겠습니다."),
            D(AncientRouteAction.Relay,"비상등 연결","설비원 해진","마지막 배전소까지 어두워요. 이 중계기를 살리면 길을 볼 수 있어요.","입자를 보충한 뒤 수광부를 조준하겠습니다.","복구 전류가 지나가면 바닥의 안내등도 켜질 겁니다.","켜졌어요. 이제 작업장 끝까지 걸어갈 수 있겠네요.","전력은 주민에게 먼저 돌려주세요."),
            D(AncientRouteAction.Talk,"밝아진 작업장","설비원 해진","불이 들어오니 퇴근표가 보이네요. 퇴근한 걸로 돼 있는 사람이 아직 안에 있어요.","명단과 실제 인원을 대조하겠습니다.","재하라는 작업자예요. 마지막 교대 때 못 봤어요.","동쪽 봉쇄 작업선으로 가면 출입 기록이 남아 있습니다.","그 기록을 확인하고 직접 데리고 나오겠습니다."),
            D(AncientRouteAction.Blade,"폐쇄 작업선","안전요원 유리","잠금판 때문에 비상문을 손으로도 열 수 없어요.","주민 쪽으로 파편이 튀지 않게 물러나 주세요.","원래 비상문에는 이런 봉인을 달지 않습니다.","문이 열렸어요. 안에는 재하 한 명이 남은 것 같습니다.","한 명이라는 말도 직접 확인한 뒤에 쓰겠습니다."),
            D(AncientRouteAction.Ambush,"빈 대피 구역","안전요원 유리","사람을 찾으러 갔더니 경비가 대피 완료라고 길을 막았어요.","구조 중입니다. 경고에 따르지 않으면 제압하겠습니다.","대피 확인서를 보여 달라고 하니 무기를 들었어요.","확인서는 안전 단말에서 출력할 수 있어요.","명령서보다 안에 있는 사람을 먼저 보겠습니다."),
            D(AncientRouteAction.Talk,"먼저 작성된 확인서","교대원 서진","재하가 사인한 적 없는데 퇴거 확인에 서명이 있어요.","서명 시각과 문이 잠긴 시각을 확인해 주세요.","확인서는 밤 열 시, 문이 잠긴 건 열한 시입니다. 순서가 거꾸로예요.","그 시간에 재하는 저와 같이 작업 중이었어요.","두 분의 증언을 따로 받아 같은 기록에 묶겠습니다."),
            D(AncientRouteAction.Blade,"잔류실 통신함","교대원 서진","잔류실 호출선까지 판으로 막혔어요. 안에서 두드리는 소리만 납니다.","통신함 덮개를 열겠습니다. 안쪽에는 손대지 마세요.","재하가 세 번씩 두드려요. 교대 때 쓰던 신호입니다.","응답이 들립니다. 조금 더 가면 잠긴 방이 나와요.","살아 있다는 걸 확인했습니다. 계속 응답해 주세요."),
            D(AncientRouteAction.Ambush,"귀환로 확보","대피요원 다솔","안전 통로에 경비 둘이 남아 있어요. 작업자가 지나가면 다시 잡힙니다.","재하가 나오기 전에 통로를 확보하겠습니다.","여기는 원래 주민 대피로예요. 화물 통제 구역이 아닙니다.","이제 의료반을 부를 수 있겠어요.","부상 여부를 확인하고 직접 인계하겠습니다."),
            D(AncientRouteAction.Talk,"실제 인원","대피요원 다솔","명단을 고치면 대피 완료 실적이 떨어진다더군요.","실적보다 실제 인원을 먼저 적어 주세요.","남은 사람 한 명을 적는 게 이렇게 어려울 줄 몰랐어요.","의료반은 출구에서 기다릴게요. 재하와 같이 오세요.","출구까지 직접 동행하겠습니다."),
            D(AncientRouteAction.Talk,"돌아온 회수품","인계원 세림","회수한 코어는 봉인했습니다. 그런데 다른 인계 차량이 먼저 배정돼 있어요.","배정 시각을 보여 주세요. 검거 보고와 비교하겠습니다.","경위님이 범인을 잡기 전 시각입니다.","우연인지 모르겠지만 같은 승인번호가 반복됩니다.","추측은 빼고 시각과 번호를 먼저 보내겠습니다."),
            D(AncientRouteAction.Blade,"잘린 송신선","인계원 세림","로컬 기록을 보내려는데 송신함 위에 차폐판이 붙었어요.","사본을 보낼 수 있도록 차폐판을 제거하겠습니다.","정식 인계선은 열려 있는데 경찰 사본선만 막혔습니다.","송신함이 응답합니다. 동쪽 정비교에 중계기가 있어요.","원본을 넘겨도 사본은 남아 있어야 합니다."),
            D(AncientRouteAction.Wire,"하부 정비교","교량원 이든","바닥 교량은 끊겼어요. 천장 고정점은 안전 검사를 마쳤습니다.","와이어로 상부 작업대를 거쳐 가겠습니다.","위쪽 파란 중계기에서 E로 접속해 주세요. 내려오면 제가 연결을 확인할게요.","중계기 접속이 확인됐어요. 이쪽 발판도 다시 쓸 수 있습니다.","구조 인력에게 이 경로를 공유해 주세요."),
            D(AncientRouteAction.Wire,"움직이는 정비 크레인","교량원 이든","다음 구간은 크레인을 타면 더 빠릅니다. 천장만 따라가도 건널 수 있어요.","안전한 경로부터 확인하겠습니다.","멈출 곳은 위쪽 중계기 작업대예요. 중간 바닥에도 쉴 곳이 있습니다.","통신선이 이어졌어요. 송신탑까지 갈 수 있겠네요.","빠르게 갈 수 있는 길과 구조용 길을 함께 남기겠습니다."),
            D(AncientRouteAction.Ambush,"사본 송신탑","송신원 나린","송신탑 앞에서 기록을 폐기하라는 경비가 기다려요.","폐기 명령은 보류합니다. 증거 보존을 위해 통로를 확보하겠습니다.","송신을 막아도 원본 인계가 중단되지는 않아요. 사본만 못 남깁니다.","탑에 접근할 수 있습니다. 이제 마지막 전송을 해 주세요.","삭제하려 했다는 기록까지 함께 보냅니다."),
            D(AncientRouteAction.Talk,"올라갈 권리","송신원 나린","포인트가 올라갔다고 알림이 떴어요. 이제 위에서 살 수 있겠네요.","먼저 코어의 수령처를 확인해야 합니다.","권한이 생겨도 엘리베이터는 직접 타야 해요. 아래층 출입 권한도 남습니다.","생활부에서 코어를 들고 달아나는 사람을 봤다는 신고가 왔어요.","이 사건과 연결되는지 길을 따라 확인하겠습니다."),
            D(AncientRouteAction.Talk,"배급 줄 끝","주민 지수","코어 운반함을 든 사람이 저쪽으로 뛰었어요. 배급원은 아니었어요.","어떤 길로 갔습니까? 쫓아가지는 마세요.","진료소 담장 쪽이요. 큰 트럭이 아니라 작은 운반함을 끌었어요.","아이들은 급식소로 보냈어요. 길만 안전하게 해 주세요.","주민 이동로를 확보하면서 흔적을 따라가겠습니다."),
            D(AncientRouteAction.Ambush,"골목의 길막이","주민 지수","도둑이 간 뒤 저 둘이 골목을 막았어요. 지나가려면 돈을 내래요.","뒤로 물러나세요. 주민 통행을 막을 권한은 없습니다.","코어를 판 돈으로 통행료도 받겠다는 말까지 했어요.","길이 열렸네요. 진료소도 이제 사람을 받을 수 있겠어요.","다친 분부터 이동하세요. 동쪽 흔적은 제가 확인합니다."),
            D(AncientRouteAction.Talk,"빈 냉장 장치","의료원 주희","약품 냉장 장치가 꺼졌어요. 오늘 코어만 없어진 게 아닙니다.","배급이 끊긴 첫날은 언제입니까?","사흘 전이에요. 장부에는 매일 정상 수령으로 돼 있어요.","오늘 도둑을 잡아도 그 사흘은 설명되지 않겠네요.","이번 절도와 이전 미수령을 따로 조사하겠습니다."),
            D(AncientRouteAction.Blade,"진료소 뒷문","의료원 주희","훔친 운반함이 철문을 찌그러뜨렸어요. 들것을 내보낼 수가 없어요.","걸린 판을 잘라 들것이 지나갈 폭을 확보하겠습니다.","바퀴 자국이 동쪽 적치장까지 이어져요.","환자부터 옮길게요. 운반함의 파란 표식을 기억해 주세요.","같은 표식이 있는지 다음 골목에서 확인하겠습니다."),
            D(AncientRouteAction.Ambush,"흔적 지우는 경비","청소원 채운","바닥을 덮고 있길래 청소인 줄 알았어요. 운반함 자국만 지우더군요.","안전한 곳에 계세요. 흔적을 훼손하지 못하게 막겠습니다.","폐차장 방향의 자국은 아직 남았어요.","표식 있는 천 조각을 여기서 주웠습니다.","발견한 위치를 함께 적고 확보하겠습니다."),
            D(AncientRouteAction.Talk,"같은 천 조각","청소원 채운","배급 상자에도 같은 천이 묶여 있었어요. 그런데 이번엔 겉을 뒤집었더군요.","출처를 숨기려 했을 수 있겠군요.","안쪽에 창고 번호가 찍혀 있어요. 동쪽 폐차장과 이어진 곳입니다.","길은 한쪽으로 이어집니다. 위쪽 감시등을 조심하세요.","표식과 바퀴 자국이 가리키는 곳으로 가겠습니다."),
            D(AncientRouteAction.Throw,"막힌 폐차 통로","폐차공 정원","버려진 차가 운송문을 막고 있어요. 저 고정판에 부딪치면 문이 열릴 겁니다.","와이어로 차를 붙잡아 한 바퀴 돌린 뒤 던지겠습니다.","와이어 모드에서 차를 좌클릭하고 마우스로 고정판을 겨누세요.","부서진 조각도 파란 입자가 되네요. 그냥 버릴 게 없군요.","우클릭으로 모아 다음 위협에 쓰겠습니다."),
            D(AncientRouteAction.Ambush,"적치장 감시원","폐차공 정원","조직원이 배달원들을 세워 놓고 운반함을 검사해요.","검사는 여기까지입니다. 주민들에게서 떨어지세요.","차나 상자를 던지면 무장을 깨뜨릴 수 있어요.","배달원들이 빠져나갔습니다. 동쪽 상자 운송로로 가세요.","도주로와 주민 이동로를 분리해서 확보하겠습니다."),
            D(AncientRouteAction.Throw,"상자 운송문","운반원 하온","작은 상자로도 저 잠금판을 부술 수 있어요. 문 안에 운반함이 있습니다.","주민 없는 방향으로 투척하겠습니다.","한 바퀴 돌고 나면 커서 방향으로 날아가요. 그동안 고정판을 겨누세요.","운반함에 창고 인장이 남았어요. 도둑이 포장만 바꾼 겁니다.","인장을 훼손하지 않고 확보하겠습니다."),
            D(AncientRouteAction.Talk,"포장만 바뀐 코어","운반원 하온","배급품은 흰 상자였어요. 여기선 검은 상자에 넣어 팔더군요.","내용물의 일련번호는 그대로입니까?","네. 겉면 번호만 덧칠했습니다. 같은 물건이라는 증거예요.","두목의 창고로 가는 통로는 감시 구역과 연결돼 있어요.","이 번호와 진료소 배정 번호를 대조하겠습니다."),
            D(AncientRouteAction.Ambush,"연결로의 매복","정비원 시온","도둑이 여기서 경비에게 운반함을 넘겼어요. 혼자 한 일이 아니에요.","넘긴 장소에서 물러나세요. 현장을 확보합니다.","경비 둘은 아직 근처에 있어요. 바닥 자국을 지키고 있더군요.","받는 사람이 있다는 걸 직접 봤어요. 제가 증언하겠습니다.","도둑과 조직의 인계가 이어졌다는 진술로 남기겠습니다."),
            D(AncientRouteAction.Relay,"주민 우회문","정비원 시온","주민 우회문 전원이 끊겨 있어요. 조직이 감시 통로만 열어 놨습니다.","수광부에 전력을 넣어 대피로를 열겠습니다.","옆 예비판을 베면 입자가 나옵니다. 문에 쓸 만큼은 남아 있어요.","주민들은 우회할 수 있어요. 경위님 앞에는 감시 구역이 남았습니다.","감시등이 지나가는 틈을 이용하겠습니다."),
            D(AncientRouteAction.Talk,"빛이 지나가는 시간","야간원 세아","불빛에 들어가면 들켜요. 경고 뒤에 레이저가 날아오거나 로봇이 나타나요.","불빛이 지나가는 방향과 엄폐물을 확인하겠습니다.","기둥 뒤에선 안 보여요. 빛이 반대로 돌 때 다음 기둥으로 가세요.","경고가 뜨면 멈추지 말고 엄폐물 뒤로 벗어나세요.","다른 주민들은 이미 열린 우회문으로 보내 주세요."),
            D(AncientRouteAction.Blade,"감시망 보조함","야간원 세아","보조함에 민간 배급선이 연결돼 있어요. 조직이 전기까지 가져다 쓰는 겁니다.","표식 덮개를 열고 연결 번호를 기록하겠습니다.","이 판을 열어도 감시등은 멈추지 않아요. 엄폐부터 확인하세요.","행정구 보급 승인 번호가 보이네요. 몰래 들여온 물건이 아니었어요.","승인이 있었다는 것과 누가 썼는지는 나눠 조사하겠습니다."),
            D(AncientRouteAction.Wire,"상부 감시 통로","외벽공 다온","바닥 순찰을 피하려면 위로 가세요. 상부 중계기에 발판이 있습니다.","천장 고정점을 이용해 접근하겠습니다.","공중 장치를 블레이드로 베면 반동으로 조금 더 올라갈 수 있어요.","위쪽 접속이 확인됐습니다. 다음 중계기도 같은 높이에 있어요.","불빛과 발판을 번갈아 확인하며 이동하겠습니다."),
            D(AncientRouteAction.Wire,"외벽 우회교","외벽공 다온","중간에 쉬는 발판도 있어요. 빠르게 건너려다 감시등에 걸릴 필요는 없습니다.","다음 상부 접속점까지 이동하겠습니다.","중앙의 큰 틈은 천장 와이어로 넘으세요. 길 자체는 끊기지 않았습니다.","외벽 통로가 이어졌어요. 본거지 쪽에서도 감시등이 돕니다.","진입로가 확보되면 주민에게 돌아오라는 신호를 보내세요."),
            D(AncientRouteAction.Ambush,"본거지 외벽 경비","외벽공 태린","저 경비는 주민 출입증도 받지 않아요. 창고 인장만 봅니다.","주민 통로에서 무장한 경비를 제압하겠습니다.","벽 안쪽으로 코어 운반 소리가 계속 들립니다.","경비가 물러났어요. 벽의 승인판을 확인할 수 있습니다.","운송이 이어지는 동안 흔적을 따라갑니다."),
            D(AncientRouteAction.Talk,"보급 승인판","외벽공 태린","같은 승인번호가 코어 상자와 감시 장비에 모두 찍혀 있어요.","밀매품과 보안 장비가 같은 길로 들어왔군요.","주민은 배급을 기다리는데 창고 전기는 한 번도 꺼지지 않았어요.","안쪽으로 가면 적재실과 로봇 격납고가 있습니다.","코어와 거래 원장을 함께 확보하겠습니다."),
            D(AncientRouteAction.Throw,"창고 화물문","창고원 우진","두목이 코어를 로봇 안으로 옮기래요. 저는 더는 안으로 못 들어갑니다.","상자를 고정판에 던져 화물문을 열겠습니다.","화물문은 고정판이 부서지면 수동으로 열립니다. 상자는 옆에 있어요.","문이 열렸어요. 작업자들은 옆 출구로 나갈게요.","출구를 막지 마세요. 무장한 사람만 안에 남으십시오."),
            D(AncientRouteAction.Ambush,"적재실 경비","창고원 우진","경비가 코어보다 원장을 먼저 챙기려 해요.","증거를 가지고 나갈 수는 없습니다. 통로를 확보합니다.","두목은 격납고에 있어요. 큰 로봇을 준비하고 있습니다.","여기 상자는 주민 배정품입니다. 아직 번호가 남아 있어요.","회수 목록에 번호를 적고 격납고로 갑니다."),
            D(AncientRouteAction.Blade,"이중 적재함","검수원 수아","상자를 열어 보면 안에 더 작은 봉인함이 있어요. 번호가 서로 다릅니다.","바깥 고정판만 절단해 내부 번호를 확인하겠습니다.","불완전 검사 표시가 있는 코어도 섞여 있습니다.","두목이 바로 그 코어를 로봇에 넣겠다고 했어요.","불안정한 코어가 전투에 쓰일 수 있습니다. 전원 물러나세요."),
            D(AncientRouteAction.Talk,"서로 다른 수량","검수원 수아","여기 물량을 전부 돌려줘도 생활부 미수령을 채울 수 없어요.","오늘의 절도로 전체 부족분을 덮을 수는 없겠군요.","이 창고로 오기 전부터 장부에서 빠진 코어가 있습니다.","원장은 두목이 갖고 있어요. 수령처를 직접 지웠다는 말도 들었습니다.","확인되지 않은 말은 따로 적고 원본을 확보하겠습니다."),
            D(AncientRouteAction.Relay,"격납고 안전 전원","기술원 로하","안전 전원을 살리면 로봇의 준비 동작을 볼 수 있어요. 어둠 속에선 위험합니다.","입자 레이저로 조명을 복구하겠습니다.","충전한 주먹이 날아오면 와이어로 돌려보내세요. 일반 탄환은 피해야 합니다.","조명이 켜졌습니다. 로봇 양팔과 중앙 코어가 보여요.","주민 대피를 마무리하세요. 안쪽은 제가 맡겠습니다."),
            D(AncientRouteAction.Talk,"격납고 앞의 침묵","기술원 로하","두목은 부하를 먼저 내보낼 거예요. 자신은 로봇 안에 숨겠죠.","부하들이 투항할 기회도 주겠습니다.","미사일을 부수면 입자가 나와요. 큰 배리어가 켜지면 모은 에너지를 쓰세요.","여기까지 온 사람은 없었어요. 다시 나올 때도 길은 열어 두겠습니다.","코어를 주민에게 돌려주고, 원장이 가리키는 다음 곳으로 가겠습니다.")
        };
        static AncientRouteStop O(AncientRouteAction a,string title,string who,string problem,string reply,string evidence,string outcome,string closing)
        {return new AncientRouteStop(a,title,who,problem,reply,evidence,outcome,closing,true);}
        static readonly AncientRouteStop[] OptionalStops={
            O(AncientRouteAction.Talk,"식지 않은 도시락","도시락 배달원 유진","아직 따뜻한데 교대가 끝났대요. 어느 문으로 가져가야 할지 모르겠어요.","오늘 실제로 근무한 인원을 확인 중입니다.","빈 도시락은 내려오고 새 도시락은 올라가요. 사람 얼굴보다 상자를 더 많이 봅니다.","안에 남은 사람에게 전해 주세요. 제 몫은 나중에 먹으면 돼요.","사람이 어디 있는지 확인되면 배달 길도 알려드리겠습니다."),
            O(AncientRouteAction.Blade,"막힌 냉각 밸브","냉각공 윤재","냉각 밸브 위에 잔해가 걸렸어요. 압력이 오르기 전에 치워야 합니다.","노란 고정판을 잘라 잔해를 분리하겠습니다.","주민 난방과 같은 배관이라 함부로 전원을 끌 수 없어요.","밸브가 돌아갑니다. 오늘 밤은 온수가 나올 거예요.","작은 복구도 작업 기록에 남겨 주세요."),
            O(AncientRouteAction.Talk,"수리한 출근 시계","시계 수리공 기현","출근 시계는 고쳤어요. 그런데 지각으로 깎인 점수는 못 고친답니다.","고장 기간을 적은 확인서를 받을 수 있습니까?","시계가 멈춘 동안에도 기록은 한 줄씩 쌓였어요. 늦었다는 기록만요.","수리 부품과 날짜를 같이 드릴게요. 누군가는 봐 주겠죠.","현장 확인서에 첨부하겠습니다. 원본은 보관하세요."),
            O(AncientRouteAction.Relay,"작은 휴게실","휴게실 관리원 연수","의자 열 개가 있는 방인데 비상등 하나를 못 켜고 있어요.","수광부에 에너지를 넣으면 됩니까?","예. 옆 예비판을 잘라 입자를 모아 주세요. 잠깐 앉을 곳만 있으면 됩니다.","조명이 켜졌어요. 교대원들이 따뜻한 곳에서 기다릴 수 있겠네요.","구조 인력이 올 때까지 이곳을 대기 장소로 쓰세요."),
            O(AncientRouteAction.Talk,"벽에 남은 키 자국","주민 아린","아빠가 여기서 제 키를 재 줬어요. 공장을 옮기면 이 벽도 없어져요?","옮긴다는 결정은 아직 못 봤어. 그 자국이 있다는 건 내가 기억할게.","위층 집으로 가면 천장도 더 높을까요? 키가 커도 괜찮겠죠?","사진은 찍었어요. 그래도 이 자국이 남았으면 좋겠어요.","지금은 안전한 곳에서 기다려. 돌아올 길부터 지켜 줄게."),
            O(AncientRouteAction.Ambush,"예비 부품 보관소","부품원 승아","도망치던 경비가 예비 부품을 가져가려 해요. 저걸 잃으면 복구를 못 합니다.","통로에서 떨어지세요. 남은 경비를 제압하겠습니다.","이 부품은 주민 배전함에도 들어갑니다. 무기만 고치는 게 아니에요.","부품을 지켰어요. 다음 구조 요청에도 쓸 수 있겠네요.","사용한 수량과 남은 수량을 직접 확인해 주세요."),
            O(AncientRouteAction.Talk,"이름을 쓰는 자리","대피 기록원 보민","빈칸에는 사유만 적으래요. 이름을 적을 칸은 없어요.","별지에 실제 인원 명단을 붙이면 됩니다.","규격에 없어서 반려될 수도 있어요. 그래도 붙일까요?","안에 남은 사람 이름부터 적었습니다. 이제 빈칸은 아니에요.","제가 현장 확인자로 서명하겠습니다."),
            O(AncientRouteAction.Blade,"놓고 간 작업 가방","정비 수습 예찬","재하 씨 가방이 잔해 밑에 있어요. 약이 들어 있다고 했습니다.","가방에 닿지 않게 덮개만 잘라내겠습니다.","퇴거 명단을 믿었으면 가방도 그냥 버렸을 거예요.","가방은 의료반에 맡길게요. 직접 찾으러 오면 좋겠네요.","꺼낸 위치와 인계받은 사람도 적어 두세요."),
            O(AncientRouteAction.Talk,"비어 있는 작업복","세탁원 지율","세탁기에 작업복이 남았어요. 대피가 끝났다면 가져갈 사람이 있어야 하잖아요.","남은 물건을 폐기하지 말고 보관해 주세요.","사람이 없어졌다고 옷까지 없는 물건으로 적지는 않겠습니다.","옷걸이에 이름표를 달아 뒀어요. 돌아오면 찾기 쉬울 거예요.","확인되지 않은 실종과 대피를 같은 말로 적지 않겠습니다."),
            O(AncientRouteAction.Talk,"복사기의 마지막 용지","인쇄원 하린","종이는 아껴 쓰라는데 폐기 명령서는 계속 출력돼요.","사본을 남길 용지가 조금 필요합니다.","주민 신청서 뒷면이 비어 있어요. 폐기하기 전에 떼어 뒀습니다.","거기 제 신청서도 있어요. 이번엔 다른 기록이라도 살아남겠네요.","신청서 번호가 있는 면은 가리지 않겠습니다."),
            O(AncientRouteAction.Wire,"상부 점검 기록","정비공 루안","위쪽 점검함에는 수정 전 송신 상태가 남아 있어요. 필수 인계품은 아닙니다.","갈 수 있는 경로라면 확인하겠습니다.","천장과 크레인을 이어 타면 위 작업대에 닿아요. 가운데 착지대에서 쉬어도 됩니다.","원격 차단이 걸리기 전에도 중계기는 정상 작동했군요.","사본선의 고장이라는 설명과 다릅니다. 보조 자료로 남기죠."),
            O(AncientRouteAction.Talk,"아래로 보내는 편지","우편원 나겸","위로 가는 서류는 우선인데 아래로 오는 답장은 늘 밀려요.","답장을 기다리는 주민이 많습니까?","서류는 올라갔으니 곧 올라갈 수 있다고 생각하니까요. 기다리는 동안 집도 못 비워요.","다음 교대 때라도 답장을 나눠 줄 수 있으면 좋겠습니다.","윗층에서 접수 여부를 확인할 수 있다면 확인하겠습니다."),
            O(AncientRouteAction.Talk,"나란한 식권","식권 배급원 유나","가족인데 식권 사용 구역이 다릅니다. 포인트가 달라서요.","오늘은 같은 대피 장소에서 식사를 받을 수 있게 하겠습니다.","같이 살 자격을 숫자로 나누면 식탁부터 갈라져요.","아이 몫을 어른 몫 옆에 뒀어요. 오늘만큼은 같이 가져가도 되겠죠.","현장 대피 급식으로 처리하겠습니다."),
            O(AncientRouteAction.Relay,"진료소 보조 냉각기","약제사 지안","주 전원은 없어도 보조 냉각기만 켜면 약을 조금 더 지킬 수 있어요.","입자를 모아 임시 전력을 넣겠습니다.","전력을 너무 오래 모으실 필요는 없어요. 수광부에 닿게만 쏴 주세요.","온도가 내려갑니다. 도둑을 잡을 때까지 버틸 수 있겠어요.","코어를 회수하면 의료 배정을 먼저 확인하겠습니다."),
            O(AncientRouteAction.Talk,"이사하지 못한 열쇠","열쇠공 은찬","승진해서 이사한 손님이 예전 열쇠를 다시 만들어 달라더군요.","아래에 두고 간 가족이 있습니까?","네. 점수는 혼자 올라도 집은 혼자 정리할 수 없잖아요.","엘리베이터에서 다시 만난대요. 돌아오는 문은 남아 있어야죠.","아래로 돌아오는 통로도 막히지 않게 확인하겠습니다."),
            O(AncientRouteAction.Throw,"고철과 배급함","수거원 채린","저 판만 부수면 주민용 운반함을 꺼낼 수 있어요. 상자는 옆에 있습니다.","와이어로 상자를 던져 판을 떼겠습니다.","부서진 차를 고치는 것보다 멀쩡한 배급함을 돌려주는 게 먼저예요.","함을 찾았어요. 이제 진료소에 약을 옮길 수 있겠네요.","배급함도 회수품으로 적고 주민에게 인계하겠습니다."),
            O(AncientRouteAction.Talk,"팔리지 않는 부품","부품상 이솔","아래에서 만든 걸 위에서 고장 냈다고 하면 수리비도 아래가 내요.","반품 사유가 남아 있습니까?","전부 사용 흔적 없음이래요. 기름때가 이렇게 묻었는데요.","상자에 찍힌 번호를 보관하고 있었어요. 가져가세요.","상태를 함께 촬영하고 번호를 대조하겠습니다."),
            O(AncientRouteAction.Ambush,"배달 상자를 지키는 사람","배달원 건우","제 상자에 코어가 없다고 하니 저 경비가 물건을 다 쏟았어요.","안전한 곳으로 이동하세요. 주민 물건을 회수하겠습니다.","저는 약과 식량만 배달합니다. 저 사람들은 포인트 증명부터 내놓으래요.","내용물은 무사해요. 늦더라도 배달은 끝낼 수 있겠네요.","오늘 지연 사유는 치안 통제로 기록해 드리겠습니다."),
            O(AncientRouteAction.Talk,"꺼지지 않는 감시등","전구 수리공 지후","주민 조명은 나흘째 꺼졌는데 감시등 전구는 새것이에요.","교체 시각과 공급 번호를 확인할 수 있습니까?","네. 제 작업표에 있어요. 어디를 먼저 밝히는지도 명령이니까요.","밖의 길은 어두워도 누굴 막을지는 잘 보이게 해 놨네요.","교체표는 직접 보관하고 사본만 주십시오."),
            O(AncientRouteAction.Wire,"외벽 대피 신호","신호원 해원","상부 신호기를 켜면 반대편 주민들도 우회로가 열렸다는 걸 알 수 있어요.","천장 와이어로 접근해 접속점을 확인하겠습니다.","높은 작업대에서 E로 접속해 주세요. 신호기는 경찰망과 연결돼 있지 않아요.","파란 등이 켜졌어요. 주민들이 움직이기 시작했습니다.","감시등과 혼동하지 않도록 정해진 신호로 유지하세요."),
            O(AncientRouteAction.Talk,"검문을 통과한 물건","외벽 점검원 유림","코어 상자는 검문을 그냥 지나갔어요. 사람만 세워 놓고 점수를 봤죠.","화물에는 별도 통과 코드가 있습니까?","상층 승인 화물이라고 뜨면 검사 항목이 사라져요.","검문 기록에는 문제없음 한 줄만 남습니다.","검사를 하지 않은 것과 문제가 없는 것은 구분하겠습니다."),
            O(AncientRouteAction.Blade,"갇힌 청소 장비","창고 청소원 단비","청소 장비 충전함에 누가 제 짐을 넣고 잠갔어요. 나갈 수가 없었습니다.","고정판을 잘라 짐을 꺼내 드리겠습니다.","짐을 못 찾으면 일을 끝내지 못한 걸로 처리한대요.","이제 대피할 수 있어요. 안쪽에는 두목 부하들만 남았습니다.","사람보다 짐이 먼저라는 규정은 따르지 않으셔도 됩니다."),
            O(AncientRouteAction.Ambush,"장부 소각 준비","창고 기록원 유빈","보조 장부까지 태우려고 경비가 왔어요. 원장과 대조할 자료입니다.","소각을 멈추고 경비를 제압하겠습니다.","원장은 두목에게 있지만 이 장부엔 실제 반입 날짜가 남아 있어요.","불을 붙이기 전에 막았네요. 기록을 가져가 주세요.","원장을 확보한 뒤 서로 맞지 않는 부분을 찾겠습니다."),
            O(AncientRouteAction.Talk,"로봇을 고친 사람","전직 설계원 정후","저 로봇은 원래 무거운 코어를 옮기던 기계예요. 사람이 탈 이유는 없었습니다.","무기로 바뀐 건 언제입니까?","주먹을 분리하고 배리어를 붙인 뒤부터요. 냉각 여유는 그대로인데 출력을 올렸습니다.","중앙 코어가 열릴 때 외부 에너지가 들어가면 과부하가 납니다.","주민이 다치지 않도록 그 틈을 이용하겠습니다.")
        };
        public static readonly AncientRouteStop[] Stops=BuildStops();
        static AncientRouteStop[] BuildStops()
        {
            var result=new AncientRouteStop[72];
            for(int sector=0;sector<24;sector++)
            {result[sector*3]=RequiredStops[sector*2];result[sector*3+1]=RequiredStops[sector*2+1];result[sector*3+2]=OptionalStops[sector];}
            return result;
        }

        public static string FollowUp(int id)
        {
            switch(id)
            {
                case 0:return "원본을 확보하겠습니다. 도장이 찍힌 시각과 실제 퇴근 시각을 함께 남기죠.";
                case 2:return "안에 남은 작업자부터 확인하고 있습니다. 아직 식사를 못 한 분도 있을 겁니다.";
                case 4:return "주민 물량을 재는 쪽도 같은 시간에 작동했습니까?";
                case 7:return "두 전표를 같이 보관해야 수정된 항목을 찾을 수 있습니다.";
                case 8:return "시계가 고장 났다는 걸 확인할 자료를 받을 수 있겠습니까?";
                case 13:return "같은 현장인데 서로의 접수 상황도 확인하지 않는 겁니까?";
                case 14:return "키가 자라는 건 걱정하지 마. 이 벽의 기억은 사진으로도 남겨 두자.";
                case 16:return "재하 씨가 마지막으로 들어간 작업선이 어디입니까?";
                case 20:return "붙여 주세요. 규격에 없다는 이유로 사람을 빼면 안 됩니다.";
                case 21:return "확인서에 적힌 시각의 재하 씨 위치를 증언해 주실 수 있습니까?";
                case 25:return "남아 있다는 사실을 확인했으니 이번엔 지우지 못할 겁니다.";
                case 26:return "주인이 돌아왔을 때 찾을 수 있도록 구분해 두십시오.";
                case 27:return "검거 전에 회수품 분류가 끝났다는 거군요. 다른 기록에도 같은 번호가 있습니까?";
                case 29:return "제 보고서 때문에 주민 기록까지 없어져선 안 됩니다.";
                case 34:return "필요하면 다시 내려오겠습니다. 올라가기 전에 들어온 신고가 있습니까?";
                case 35:return "기다리는 동안 배급과 일자리는 계속 유지됩니까?";
                case 36:return "그 길로 가겠습니다. 배급을 기다리던 주민들은 어디에 있습니까?";
                case 38:return "대피한 가족이 서로를 찾는 데까지 점수를 따질 필요는 없습니다.";
                case 39:return "오늘 신고된 절도보다 배정 중단이 먼저였군요.";
                case 43:return "창고까지 다른 갈림길이 있습니까?";
                case 44:return "새 주소로 옮겨도 아래에 남은 사람이 없어지는 건 아니죠.";
                case 49:return "포장 흔적을 확보하겠습니다. 물건이 도착한 곳까지 가 보죠.";
                case 50:return "사용된 부품이라는 걸 대조할 출고 번호가 필요합니다.";
                case 54:return "이미 빛에 걸렸다면 어디로 피해야 합니까?";
                case 56:return "주민 조명 복구보다 감시 장비 교체가 먼저 승인됐군요.";
                case 61:return "전기가 계속 공급되는 곳부터 확인하겠습니다. 창고 안은 어떻게 이어집니까?";
                case 62:return "검사를 생략했다는 사실은 남습니까?";
                case 67:return "입고 장부와 원장을 직접 맞춰 보겠습니다. 원장은 어디 있습니까?";
                case 70:return "준비하고 들어가겠습니다. 주민 대피로는 계속 열어 두십시오.";
                case 71:return "냉각 여유가 없는데 외부 에너지가 더 들어오면 어떻게 됩니까?";
                default:return "확인한 사실을 그대로 기록하겠습니다.";
            }
        }
        public static string ShortHint(AncientRouteAction action)
        {
            switch(action)
            {
                case AncientRouteAction.Blade:return "고정판 베기";
                case AncientRouteAction.Relay:return "입자 수집 후 레이저";
                case AncientRouteAction.Ambush:return "경비 2명 제압";
                case AncientRouteAction.Wire:return "상부 접속점에서 E";
                case AncientRouteAction.Throw:return "와이어 물체 투척";
                default:return "E: 증언";
            }
        }
        public static string Hint(AncientRouteAction action)
        {
            switch(action)
            {
                case AncientRouteAction.Blade:return "공격 모드 · 노란 고정판을 블레이드로 베기";
                case AncientRouteAction.Relay:return "노란 예비판 베기 · 우클릭 수집 · 좌클릭 꾹 누른 뒤 수광부에 레이저";
                case AncientRouteAction.Ambush:return "전조를 피하며 경비 2명 제압 · 투척물 베기";
                case AncientRouteAction.Wire:return "천장 와이어로 상부 접속점에 도착 · E";
                case AncientRouteAction.Throw:return "와이어 모드 · 차나 상자 좌클릭 · 파란 고정판에 투척";
                default:return "E · 주민 증언 듣기";
            }
        }
    }
}
